import { i18nValidationMessage } from 'nestjs-i18n';
import { IsUUID, IsOptional, IsString } from 'class-validator';
import { Transform } from 'class-transformer';
import { TrimStringTransformer } from '../../../common/transformers/trim-string.transformer';

export class CreateIncidenciaDto {
  @IsUUID('7', {
    message: i18nValidationMessage(
      'validation.EL_ID_DE_LA_RECEPCI_N_DEBE_SER_UN_UUID_V'
    ),
  })
  recepcionId: string;

  @IsOptional()
  @IsUUID('7')
  pedidoId?: string;

  @IsOptional()
  @Transform(TrimStringTransformer.transform)
  @IsString()
  observacionesRecepcion?: string;
}

export class CreateIncidenciaResuelaDto {
  @IsUUID('7', {
    message: i18nValidationMessage(
      'validation.EL_ID_DE_LA_INCIDENCIA_DEBE_SER_UN_UUID'
    ),
  })
  idIncidencia!: string;

  @IsOptional()
  @IsUUID('7')
  idUsuarioResolutor?: string;

  @IsOptional()
  @Transform(TrimStringTransformer.transform)
  @IsString()
  observaciones?: string;
}
